"""The run folder writer (AD-06)."""

import dataclasses
import json
from collections.abc import Mapping
from datetime import datetime
from pathlib import Path
from typing import Literal, cast

import numpy as np
import torch

from rllab.core.types import Box, Discrete, EpisodeResult, RunConfig, WorldSpec
from rllab.runlog.types import Checkpoint, EvalPoint, Failure, RunExistsError, RunRecord

Status = Literal["running", "finished", "incomplete", "failed"]


def to_json(value: object) -> object:
    """The JSON form of a run-folder value: dataclasses as objects of their fields (`Discrete`
    and `Box` add `"kind"`), tuples as lists, paths and datetimes as strings."""
    if dataclasses.is_dataclass(value) and not isinstance(value, type):
        fields = {f.name: to_json(getattr(value, f.name)) for f in dataclasses.fields(value)}
        kind = {Discrete: "discrete", Box: "box"}.get(type(value))
        return {"kind": kind, **fields} if kind else fields
    if isinstance(value, Mapping):
        return {str(k): to_json(v) for k, v in value.items()}
    if isinstance(value, (tuple, list)):
        return [to_json(v) for v in value]
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, np.generic):
        return value.item()
    return value


class RunWriter:
    """Writes `runs/<world>/<variant>/<name>/`; `RunExistsError` if that folder exists."""

    def __init__(self, root: Path, config: RunConfig, spec: WorldSpec) -> None:
        self.path = root / config.world / config.variant / config.name
        if self.path.exists():
            raise RunExistsError(self.path)
        (self.path / "checkpoints").mkdir(parents=True)
        self.config, self.spec = config, spec
        self.started = datetime.now()
        self._episodes = (self.path / "episodes.jsonl").open("a", encoding="utf-8")
        self._evals = (self.path / "evals.jsonl").open("a", encoding="utf-8")
        self._record("running", None, None)

    def episode(self, result: EpisodeResult) -> None:
        self._episodes.write(json.dumps(to_json(result)) + "\n")

    def eval(self, point: EvalPoint) -> None:
        """Append `point` and flush every log."""
        self._evals.write(json.dumps(to_json(point)) + "\n")
        self._episodes.flush()
        self._evals.flush()

    def checkpoint(self, pct: int, step: int, state: Mapping[str, dict[str, object]]) -> Checkpoint:
        """Save `checkpoints/ckpt_<pct>.pt`: spec and method configs as JSON forms, the state."""
        path = self.path / "checkpoints" / f"ckpt_{pct}.pt"
        saved = {
            "run": self.config.name,
            "pct": pct,
            "step": step,
            "spec": to_json(self.spec),
            "methods": to_json(self.config.methods),
            "state": dict(state),
        }
        torch.save(saved, path)
        return Checkpoint(
            self.config.name, pct, step, self.spec, dict(self.config.methods), dict(state), path
        )

    def close(self, status: str, failure: Failure | None = None) -> RunRecord:
        """Flush and close the logs, and record the run as ended with `status`."""
        self._episodes.close()
        self._evals.close()
        return self._record(cast("Status", status), datetime.now(), failure)

    def _record(self, status: Status, ended: datetime | None, failure: Failure | None) -> RunRecord:
        """Replace `run.json` atomically: write a temporary file, then rename it."""
        record = RunRecord(self.config, self.spec, self.started, ended, status, failure, self.path)
        partial = self.path / "run.json.tmp"
        partial.write_text(json.dumps(to_json(record), indent=1), encoding="utf-8")
        partial.replace(self.path / "run.json")
        return record

